namespace OpenTPW;

/// <summary>
/// The guest walk's approximation register (docs/GUESTS.md, "Walking"; docs/reverse/WALK-plan.md §11, §13). Each entry is
/// tagged <c>[APPROX:WALK-NNN]</c> at its code site. The speed model, the steering step, follow_path's arrival and
/// waypoint rules, the stuck reroute rule, the edge branch of avoid_walls and the stand point are traced from the Mac
/// binary, and so is the separation force (BIN labels at the code sites).
/// </summary>
public static class WalkApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("WALK-001", "the amount of the special ingredient is the economy record's: 50 when the ride is built (tp.exe 0x4db090 stores 0x32 at +0x198, 0x4db3b3), saved with the park and imported from an original save (mAmountOfSpecialIngredient, 0x4dcdc1), and a Sugar visit adds trunc(6 x amount / 100) (0x4fe5f8); the original's shop window shows a 0..100 amount slider for ingredient shops only (range set at 0x4b06d2; refresh 0x4b0950 hides controls 0xc086/0xc084 unless the type's ingredient is 1..4) and writes it to the object (0x4b0aa0) or to every object of that type (0x4b0ae0); OpenTPW has no slider yet"),
		("WALK-002", "avoid_walls (tp.exe 0x50e4a0, Mac 0xfdc70) models only its edge branch (the first pushing edge of +x, -x, +y, -y, 2 x the penetration) and takes the cell of the probe; the original takes the cell of the position (0x5104b0 on walk +8/+0xc, 0x50e4eb) and, when no edge pushes, runs one corner block for that cell's corner in the motion quadrant (0x50e75e, 0x50e8b3, 0x50ea07, 0x50eb5e) with the ray test 0x50cc20, which OpenTPW leaves out"),
		("WALK-003", "separation's neighbours are the guests outside rides and shops (not Using, HeldByGuard or Gone) in OpenTPW's cell lists, rebuilt every park turn in guest order with movers appended; the original (tp.exe query 0x5102f0, Mac 0x10087c) walks per-cell thing lists that are head-inserted when a thing enters a cell (0x50b6a0 via 0x4d91f0) and never rebuilt, keeps class-1 guests whatever their state, and also keeps staff (classes 4-8) and the online avatar (class 18); the neighbour position (thing +4/+6 = navigation position >> 8, written by 0x4fa2a0) matches OpenTPW's"),
		("WALK-004", "routes are OpenTPW's cell sequences (one Grid.TryStep cell per destination, the queue cells in order, Grid.FindPath for the bin and wander walks) that start at the guest's own cell and are refilled five waypoints at a time from the stored route; the stuck reroute prepends the current cell to the rest; the original searches from the guest's cell at every SetDest (0x510100, setup 0x50f8e0, search 0x511420 = line-and-boundary search 0x511470 plus refinement 0x5108a0), again at each refill (0x50efce) and at the stuck reroute (0x50ee79, mode 1, current cell prepended), and ends the walk when a search fails (+0x60 = +0xb8 = 1, 0x50f945)"),
		("WALK-005", "a cell is walkable when it is on the current walk (route and extra open cells), so path cells beside the route are walls; the original commits a step through the callback 0x510510 (at most one cell, diagonal steps through either L-shaped route) and the edge test 0x4d8750 with the guest's mask (walk +0xb4): path-to-path steps are always open, queue boundaries need the target's link back, other cell types and the masks 1 and 2 have their own rules; none of this is modelled"),
		("WALK-006", "a queue walk may also enter the queue cell ahead of its destination and the one behind its start, and no other cell off its route; in the original a step from a queue cell is open (edge test 0x4d8750) into a path, queue or queue-end neighbour whose link points back at it, or into a type-0x1e fixed walkway when the mask is not 2, and blocked otherwise; OpenTPW does not read the cell links for this"),
		("WALK-007", "no map-edit reroute: the original stamps the 16 x 16-cell block of a changed cell with a global counter (0x4d8c50/0x4d8c60, from 0x5346d0, 0x538fc0, 0x5348d0 and 0x4de1f0), and every walk step follow_path (0x50ed10) compares the stamp of the guest's block (0x4d8cd0) with the walk's +72 (0x50ed6c) and searches again (0x50f8e0 mode 1); a failed search sets +184 and ends the walk as arrived; OpenTPW reroutes only on the stuck rule"),
		("WALK-008", "guests on the arrival lanes walk off the path grid, with no wall force and every position committed; the original walks them like every guest (route search 0x50f8e0, commit 0x510510 and edge test 0x4d8750 with the walk mask), the lane cells being type 0x1e or path from map init 0x536490, so only map-edge, entrance-building, water, ride and queue cells could push or refuse them"),
		("WALK-009", "the progress history compares raw remaining distances inside the five-waypoint window and skips the first step after route setup; the original's progress is ONE - trunc(remaining x ONE / +160) (0x50fd40; ONE when arrived or +160 is 0), where +160 is the whole route's octile length from the position at setup or refill, compared (<=) with +172 (0x50f5c7), which setup and every refill reset to 0 together with the history +176 (0x50f8e0)"),
		("WALK-010", "the needs phase that gates the toilet speed term compares the park turn with OpenTPW's guest id; the original compares the low two bits of the tick with the thing id (tp.exe 0x501676), taken from one pool of 10239 slots shared by every thing kind (allocator 0x516270, ids 1, 2, 3, ... on a fresh park, freed ids reused last-in first-out after the turn's deferred destroy), so the phase depends on the whole construction and destroy history")
	};
}
